-- ============================================================
-- 003_cargos_msp.sql
-- Cargos del hospital segun el PDF "Estructura de puestos de hospitales basicos de 30 camas o mas del MSP":
-- 112 puestos con su grado, rol del puesto y nivel jerarquico, mas Subdirector/a y Jefe/a de Area,
-- que el PDF no trae pero el flujo de aprobacion necesita.
-- Responsabilidad y funciones son textos breves por tipo de puesto; Talento Humano puede ajustarlos despues.
-- Se corre una sola vez por hospital, despues de 002_estructura_areas.sql. Requiere MySQL 8.0.19 o superior (VALUES ROW).
-- ============================================================
SET NAMES utf8mb4;

-- Hospital al que se cargan los cargos (nombre tal como esta en empresas.nombre)
SET @hospital = 'Hospital Básico San Andrés';
SET @empresa_id = (SELECT id FROM empresas WHERE nombre = @hospital);

-- Puestos del PDF. p: lista de puestos (nombre con grado, tipo de puesto, grado, rol); f: textos por tipo de puesto.
-- nivel_jerarquico: 1 director, 4 puestos con coordinacion o supervision, 5 el resto.
-- Al final de funciones se agrega la frase de coordinacion o supervision segun el rol del puesto.
INSERT INTO cargos (empresa_id, detalle, grado, rol_puesto, nivel_jerarquico, responsabilidad, funciones)
WITH
