  f (tipo, responsabilidad, funciones) AS (
    VALUES
    ROW('DIRECTOR', 'Dirige el hospital y responde ante la Coordinación Zonal por su funcionamiento, sus resultados y el uso de sus recursos.',
      'Conduce la planificación del hospital; autoriza gastos y contrataciones según su delegación; preside los comités institucionales; supervisa la calidad de la atención; representa al hospital ante la Coordinación Zonal y otras instituciones.'),
    ROW('MED_CIRUGIA', 'Responde por la atención de los pacientes con patología quirúrgica del hospital.',
      'Evalúa y diagnostica a los pacientes quirúrgicos; indica y realiza las cirugías de su especialidad; atiende interconsultas y emergencias quirúrgicas; hace el seguimiento posoperatorio; registra la atención en la historia clínica.'),
    ROW('MED_EMERGENCIAS', 'Responde por la atención inicial y la estabilización de los pacientes que llegan a emergencia.',
      'Clasifica y atiende urgencias y emergencias; estabiliza al paciente y decide su ingreso, alta o referencia; dirige la reanimación; participa en los planes de respuesta a desastres y emergencias masivas; registra la atención en la historia clínica.'),
    ROW('MED_GINECOLOGIA', 'Responde por la atención ginecológica y de salud sexual y reproductiva de las pacientes del hospital.',
      'Evalúa y trata la patología ginecológica; atiende emergencias gineco-obstétricas; realiza cirugías y procedimientos de su especialidad; atiende interconsultas; registra la atención en la historia clínica.'),
    ROW('MED_INTERNA', 'Responde por la atención de los pacientes adultos con enfermedades clínicas, en consulta y hospitalización.',
      'Diagnostica y trata las enfermedades del adulto; hace la visita médica en hospitalización; atiende interconsultas de otros servicios; indica exámenes y tratamientos; decide altas y referencias; registra la atención en la historia clínica.'),
    ROW('MED_PEDIATRIA', 'Responde por la atención de niños y adolescentes en consulta, emergencia y hospitalización.',
      'Controla crecimiento y desarrollo; diagnostica y trata las enfermedades pediátricas; hace la visita médica en hospitalización; atiende interconsultas; decide altas y referencias; registra la atención en la historia clínica.'),
    ROW('MED_GENERAL', 'Responde por la atención médica general de los pacientes del servicio al que se le asigna.',
      'Atiende consulta, emergencia o guardia según su asignación; evalúa y trata a los pacientes; apoya a los especialistas en hospitalización y procedimientos; realiza referencias y contrarreferencias; registra la atención en la historia clínica.'),
    ROW('ODO_PEDIATRIA', 'Responde por la salud bucal de niños y adolescentes atendidos en el hospital.',
      'Diagnostica y trata la patología bucal infantil; realiza procedimientos preventivos y restaurativos en niños; maneja la conducta del paciente pediátrico; atiende interconsultas; registra la atención en la historia clínica.'),
    ROW('ODO_ENDODONCIA', 'Responde por el tratamiento de las enfermedades de la pulpa y del tejido que rodea la raíz del diente.',
      'Diagnostica enfermedades pulpares y periapicales; realiza tratamientos de conducto y retratamientos; indica e interpreta radiografías dentales; atiende interconsultas de odontología general; registra la atención en la historia clínica.'),
    ROW('ODO_ORTODONCIA', 'Responde por la corrección de las alteraciones en la posición de los dientes y los maxilares.',
      'Diagnostica maloclusiones; planifica e instala los aparatos de ortodoncia; controla la evolución del tratamiento; indica e interpreta radiografías y modelos de estudio; registra la atención en la historia clínica.'),
    ROW('ODO_GENERAL', 'Responde por la atención odontológica básica de los pacientes del hospital.',
      'Diagnostica, previene y trata caries y enfermedad periodontal; realiza extracciones y restauraciones; indica radiografías dentales; refiere a especialistas los casos complejos; registra la atención en la historia clínica.'),
    ROW('OBSTETRIZ', 'Responde por la atención del embarazo, el parto y el posparto de bajo riesgo, y del recién nacido sano al nacer.',
      'Hace el control prenatal y del puerperio; atiende partos normales y el alumbramiento; realiza la atención inmediata del recién nacido; detecta signos de riesgo y avisa al médico; orienta en planificación familiar; registra la atención en la historia clínica.'),
    ROW('ENFERMERIA', 'Responde por los cuidados de enfermería de los pacientes del servicio donde trabaja.',
      'Aplica el proceso de atención de enfermería; administra los medicamentos y tratamientos indicados; controla signos vitales y evolución del paciente; realiza curaciones y procedimientos de enfermería; registra cuidados y novedades en la historia clínica; entrega y recibe turno.'),
    ROW('MED_ANESTESIOLOGIA', 'Responde por la anestesia, el control del dolor y la seguridad del paciente durante la cirugía y su recuperación inmediata.',
      'Valora al paciente antes de la cirugía; elige y administra la anestesia; vigila al paciente durante el procedimiento; indica el manejo del dolor posoperatorio; atiende la sala de recuperación; registra el acto anestésico.'),
    ROW('MED_INTENSIVOS', 'Responde por la atención de los pacientes críticos de terapia intensiva.',
      'Valora e ingresa a los pacientes críticos; maneja ventilación mecánica, soporte hemodinámico y monitoreo; indica y ajusta tratamientos; coordina con otros especialistas; informa a la familia; decide el egreso de la unidad; registra la atención en la historia clínica.'),
    ROW('TM_IMAGEN', 'Responde por la toma correcta de imágenes diagnósticas y por la protección radiológica del paciente y del personal.',
      'Prepara al paciente y realiza radiografías y otros estudios indicados; controla la calidad de la imagen; aplica las normas de protección radiológica; opera y da mantenimiento básico al equipo; entrega las imágenes al médico y registra los estudios.'),
    ROW('LAB_CLINICO', 'Responde por el procesamiento de las muestras y la confiabilidad de los exámenes de laboratorio.',
      'Recibe y procesa muestras; realiza análisis de hematología, química sanguínea, orina, heces y microbiología; valida y entrega resultados; controla la calidad y calibra los equipos; aplica las normas de bioseguridad.'),
    ROW('TM_LAB', 'Responde por los análisis de laboratorio que se le asignan y por la calidad de sus resultados.',
      'Toma y recibe muestras; procesa los análisis en los equipos del laboratorio; verifica y registra los resultados; mantiene los reactivos y el control de calidad; cumple las normas de bioseguridad y el manejo de desechos.'),
    ROW('TM_TRANSFUSIONAL', 'Responde por la obtención, el análisis y la entrega segura de sangre y sus componentes para transfusión.',
      'Atiende y selecciona a los donantes; extrae y procesa las unidades de sangre; realiza pruebas de compatibilidad y tamizaje; almacena y despacha los componentes; registra y rastrea cada unidad; reporta las reacciones transfusionales.'),
    ROW('MED_FISIATRIA', 'Responde por el diagnóstico funcional y el plan de rehabilitación de los pacientes.',
      'Evalúa la funcionalidad y la discapacidad; prescribe terapias físicas y ayudas técnicas; supervisa al equipo de terapistas; controla la evolución del paciente; atiende interconsultas; registra la atención en la historia clínica.'),
    ROW('TM_FISICA', 'Responde por la ejecución de las terapias físicas indicadas a cada paciente.',
      'Evalúa al paciente según la indicación médica; aplica ejercicios, agentes físicos y masoterapia; enseña ejercicios para hacer en casa; registra las sesiones y la evolución; mantiene los equipos de terapia.'),
    ROW('TERAPISTA_OCUP', 'Responde por recuperar y mantener la independencia del paciente en sus actividades diarias.',
      'Evalúa las capacidades del paciente; planifica y aplica la terapia ocupacional; adapta actividades y ayudas técnicas; orienta a la familia; registra las sesiones y la evolución.'),
    ROW('TERAPISTA_LENG', 'Responde por la evaluación y la terapia de los trastornos del lenguaje, la voz, el habla y la audición.',
      'Evalúa comunicación, lenguaje y audición; aplica terapia individual; enseña a la familia ejercicios para hacer en casa; deriva los casos que necesitan otro especialista; registra las sesiones y la evolución.'),
    ROW('PSICOLOGIA', 'Responde por la evaluación y la atención psicológica de los pacientes y sus familias.',
      'Hace la entrevista y la evaluación psicológica; aplica psicoterapia individual, familiar y de grupo; atiende crisis y emergencias de salud mental; elabora informes; refiere a psiquiatría u otros servicios; registra la atención en la historia clínica.'),
    ROW('TERAPISTA_PSICO', 'Responde por el entrenamiento en habilidades de la vida diaria y la reinserción social de pacientes con problemas de salud mental.',
      'Aplica talleres y actividades de psicorrehabilitación; entrena autocuidado y habilidades sociales; trabaja con la familia y la comunidad; registra la participación y la evolución de cada paciente.'),
    ROW('QF_FARMACIA', 'Responde por el abastecimiento, el almacenamiento y la dispensación segura de medicamentos, dispositivos médicos e insumos.',
      'Programa y gestiona la compra de medicamentos; recibe, almacena y controla existencias y fechas de caducidad; valida y dispensa las recetas; hace farmacovigilancia; lleva el registro de psicotrópicos y estupefacientes; elabora informes de consumo.'),
    ROW('QF_LAB', 'Responde por los reactivos e insumos del laboratorio: su compra, almacenamiento y control.',
      'Programa la compra de reactivos e insumos; los recibe y almacena controlando condiciones y caducidad; los entrega a las secciones del laboratorio; lleva el inventario y los registros; apoya el control de calidad de los análisis.'),
    ROW('NUTRICION', 'Responde por la valoración nutricional y la alimentación de los pacientes del hospital.',
      'Valora el estado nutricional; calcula y prescribe las dietas; supervisa la preparación y distribución de la alimentación hospitalaria; da consejería a pacientes y familiares; registra la atención en la historia clínica.'),
    ROW('DOCENCIA_EXP', 'Responde por la gestión de la docencia y la investigación en el hospital acreditado.',
      'Planifica la docencia y los internados; coordina los convenios y las rotaciones de estudiantes; evalúa y da seguimiento a los proyectos de investigación; apoya la capacitación del personal; elabora informes.'),
    ROW('DOCENCIA_ANA', 'Responde por el apoyo operativo a la docencia y la investigación del hospital.',
      'Organiza las rotaciones y los registros de los estudiantes; prepara los expedientes y documentos de los proyectos de investigación; apoya la capacitación del personal; archiva y reporta la información.'),
    ROW('PLANIFICACION', 'Responde por la planificación, el seguimiento y la evaluación de los planes e indicadores del hospital.',
      'Elabora el plan operativo anual; consolida y reporta el avance de metas e indicadores; da seguimiento a los proyectos y compromisos de la gestión; prepara los informes de evaluación.'),
    ROW('CALIDAD', 'Responde por la mejora continua y el cumplimiento de los estándares de calidad en la atención.',
      'Aplica y monitorea los indicadores de calidad; audita procesos e historias clínicas; levanta y da seguimiento a planes de mejora; apoya la gestión de eventos adversos y la medición de la satisfacción del usuario; elabora informes.'),
