      'Recibe y archiva documentos y expedientes del personal; registra asistencia, permisos y vacaciones; prepara certificados y oficios; atiende consultas del personal.')
  )
SELECT @empresa_id, p.detalle, p.grado, p.rol_puesto,
       CASE WHEN p.tipo = 'DIRECTOR' THEN 1
            WHEN p.rol_puesto LIKE '%coordinación%' OR p.rol_puesto LIKE '%supervisión%' THEN 4
            ELSE 5 END,
       f.responsabilidad,
       CONCAT(f.funciones,
              CASE WHEN p.rol_puesto LIKE '%coordinación%' THEN ' Además, coordina al equipo del servicio y responde por sus resultados.'
                   WHEN p.rol_puesto LIKE '%supervisión%' THEN ' Además, supervisa la ejecución de los procesos del servicio.'
                   ELSE '' END)
FROM p
JOIN f ON f.tipo = p.tipo
WHERE NOT EXISTS (
  SELECT 1
  FROM cargos existente
  WHERE existente.empresa_id = @empresa_id
    AND existente.detalle = p.detalle
);

-- Cargos de jefatura que no vienen en el PDF: el nivel 2 y el 3 definen quien aprueba y quien escala
INSERT INTO cargos (empresa_id, detalle, grado, rol_puesto, nivel_jerarquico, responsabilidad, funciones)
SELECT @empresa_id, catalogo.detalle, catalogo.grado, catalogo.rol_puesto,
       catalogo.nivel_jerarquico, catalogo.responsabilidad, catalogo.funciones
FROM (
  SELECT
    'Subdirector/a de Hospital Básico' AS detalle,
    NULL AS grado,
    NULL AS rol_puesto,
    2 AS nivel_jerarquico,
    'Responde ante el Director por la coordinación de las áreas del hospital y lo reemplaza cuando se ausenta.' AS responsabilidad,
    'Coordina a los jefes de área; da seguimiento a los planes y metas; supervisa la atención y los servicios; atiende los asuntos que le delega el Director; subroga al Director en su ausencia.' AS funciones
  UNION ALL
  SELECT
    'Jefe/a de Área',
    NULL,
    NULL,
    3,
    'Responde por el funcionamiento de su área y por el personal a su cargo.',
    'Organiza el trabajo y los turnos del personal; revisa el cumplimiento de metas e indicadores; da el visto bueno a permisos y vacaciones de su personal; coordina con otras áreas; reporta las novedades a la Dirección.'
) AS catalogo
WHERE NOT EXISTS (
  SELECT 1
  FROM cargos existente
  WHERE existente.empresa_id = @empresa_id
    AND existente.detalle = catalogo.detalle
);

-- Verificacion: deben salir 114 cargos (1 de nivel 1, 1 de nivel 2, 1 de nivel 3)
SELECT nivel_jerarquico, COUNT(*) AS cargos FROM cargos WHERE empresa_id = @empresa_id GROUP BY nivel_jerarquico ORDER BY nivel_jerarquico;